bugs.replace:
const withCustomers: Row[] = [];
for (const order of page) {
  const rows = await db.query("select id, name, email from customers where id = $1", [
    String(order.customer_id),
  ]);
  withCustomers.push({ ...order, customer: rows[0] ?? null });
}

return withCustomers;
